#include <queue>
#include <iostream>

int main() {
    std::queue<int> q;

    q.push(10); // First in
    q.push(20);
    q.push(30); // Last in

    // Check newest element (back) without removal
    std::cout << "Newest: " << q.back() << std::endl; // Output: 30

    while (!q.empty()) {
        // Retrieve oldest element (front)
        std::cout << q.front() << " "; 
        q.pop();
    } // Output: 10 20 30 
    return 0;
}
